export const RESOURCE_DATE_FILTER_TYPES = new Set<ResourceCatalogType>(['order', 'charge'])

export function categoryIdsFromExtras(extras: Record<string, string>) {
  if (extras.category_ids) {
    return extras.category_ids
      .split(',')
      .map((id) => id.trim())
      .filter(Boolean)
  }
  if (extras.category_id && extras.category_id !== 'all') {
    return [extras.category_id]
  }
  return []
}

export function resourceCatalogFiltersActive(
  status: string,
  extras: Record<string, string>,
  type: ResourceCatalogType,
) {
  if (status !== 'all') return true
  if (categoryIdsFromExtras(extras).length > 0) return true
  if (extras.location_id) return true
  if (extras.date_from || extras.date_to) return true
  for (const group of RESOURCE_EXTRA_FILTERS[type] ?? []) {
    if ((extras[group.key] ?? 'all') !== 'all') return true
  }
  return false
}

import type { ResourceItem, ResourceType } from '@/components/form/resource-picker'
import type { SchemaTableRow } from '@/components/displaying-data/data-table-model'

function readRecordField(
  record: Record<string, unknown> | undefined,
  key: string,
): string | undefined {
  if (!record) return undefined
  const value = record[key]
  if (value == null || value === '') return undefined
  return String(value)
}

function formatMoney(record: Record<string, unknown> | undefined) {
  if (!record) return undefined
  const display = record.price_display ?? record.amount_display
  if (typeof display === 'string' && display) return display
  const amount = record.amount ?? record.price
  const currency = record.currency
  if (typeof amount === 'number' && typeof currency === 'string') {
    return `${currency.toUpperCase()} ${amount}`
  }
  return undefined
}

export function resourcePickerItemToRow(
  type: ResourceType,
  item: ResourceItem,
): SchemaTableRow {
  const record = item.resource as Record<string, unknown> | undefined

  if (type === 'product') {
    return {
      id: item.id,
      name: item.title,
      sku: item.subtitle ?? readRecordField(record, 'stock_keeping_unit') ?? '',
      image: item.image ?? '',
      status: readRecordField(record, 'status') ?? item.badge ?? '',
      price: formatMoney(record) ?? '',
      resource: item.resource,
    }
  }

  if (type === 'order') {
    return {
      id: item.id,
      name: item.title,
      status: item.badge ?? readRecordField(record, 'status') ?? '',
      amount: formatMoney(record) ?? '',
      channel: readRecordField(record, 'channel') ?? '',
      date: readRecordField(record, 'created_at') ?? '',
      resource: item.resource,
    }
  }

  if (type === 'charge') {
    const method = record?.payment_method
    const methodName =
      method && typeof method === 'object' && !Array.isArray(method)
        ? readRecordField(method as Record<string, unknown>, 'name')
        : undefined
    return {
      id: item.id,
      name: item.title,
      status: item.badge ?? readRecordField(record, 'status') ?? '',
      amount: formatMoney(record) ?? '',
      method: methodName ?? '',
      date: readRecordField(record, 'created_at') ?? '',
      resource: item.resource,
    }
  }

  return {
    id: item.id,
    name: item.title,
    status: item.badge ?? readRecordField(record, 'status') ?? '',
    amount: formatMoney(record) ?? '',
    email: readRecordField(record, 'email') ?? '',
    resource: item.resource,
  }
}

export function resourcePickerItemsToRows(
  type: ResourceType,
  items: ResourceItem[],
): SchemaTableRow[] {
  return items.map((item) => resourcePickerItemToRow(type, item))
}

/** Fallback when upstream meta has no total but hasMore is known. */
export function estimateListTotal(
  page: number,
  pageSize: number,
  rowCount: number,
  hasMore: boolean,
  metaTotal?: number,
) {
  if (metaTotal != null && metaTotal >= 0) return metaTotal
  const loaded = (page - 1) * pageSize + rowCount
  if (hasMore) return loaded + 1
  return loaded
}

import type {
  SchemaTableFilter,
  SchemaTableSchema,
  SchemaTableSelectionAction,
  SchemaTableTab,
} from '@/components/displaying-data/data-table-model'
import {
  RESOURCE_CATALOG_LABELS,
  RESOURCE_EXTRA_FILTERS,
  RESOURCE_STATUS_FILTERS,
  type ResourceCatalogType,
} from '@/lib/resource-catalog'

const RESOURCE_LIST_SELECTION_ACTIONS: SchemaTableSelectionAction[] = [
  { key: 'export', label: 'Export', icon: 'download' },
  {
    key: 'more',
    label: 'More actions',
    icon: 'more',
    presentation: 'dropdown',
    items: [
      { key: 'duplicate', label: 'Duplicate', icon: 'duplicate' },
      {
        key: 'delete',
        label: 'Delete',
        icon: 'delete',
        variant: 'destructive',
        separator: true,
      },
    ],
  },
]

function catalogStatusTabs(type: ResourceCatalogType): SchemaTableTab[] {
  return RESOURCE_STATUS_FILTERS[type].map((option) => ({
    key: option.value,
    title: option.label,
  }))
}

function catalogToolbarFilters(type: ResourceCatalogType): SchemaTableFilter[] {
  return (RESOURCE_EXTRA_FILTERS[type] ?? []).map((group) => ({
    key: group.key,
    title: group.label,
    options: group.options.filter((option) => option.value !== 'all'),
  }))
}

function listTableChrome(
  type: ResourceCatalogType,
  searchPlaceholder: string,
): Pick<
  SchemaTableSchema,
  | 'mode'
  | 'selection'
  | 'editColumns'
  | 'search'
  | 'tabs'
  | 'tabKey'
  | 'filters'
  | 'sort'
  | 'pagination'
  | 'rowActions'
  | 'selectionActions'
  | 'emptyState'
> {
  const labels = RESOURCE_CATALOG_LABELS[type]
  const toolbarFilters = catalogToolbarFilters(type)

  return {
    mode: 'server',
    selection: true,
    editColumns: true,
    search: { placeholder: searchPlaceholder, debounceMs: 300 },
    tabKey: 'status',
    tabs: catalogStatusTabs(type),
    filters: toolbarFilters.length > 0 ? toolbarFilters : undefined,
    rowActions: ['edit', 'delete'],
    selectionActions: RESOURCE_LIST_SELECTION_ACTIONS.map((action) =>
      action.key === 'export'
        ? { ...action, label: `Export ${labels.plural}` }
        : action,
    ),
    emptyState: {
      title: `No ${labels.plural} found`,
      description: 'Try another search, tab, or filter.',
      actions: [{ key: 'add', label: `Add ${labels.singular}`, icon: 'add' }],
    },
  }
}

export function resourceListSchema(type: ResourceCatalogType): SchemaTableSchema {
  const labels = RESOURCE_CATALOG_LABELS[type]
  const searchPlaceholder = `Search ${labels.plural}`
  const chrome = listTableChrome(type, searchPlaceholder)

  if (type === 'product') {
    return {
      ...chrome,
      key: 'resource-list-product',
      sort: {
        fields: [
          { key: 'name', title: 'Product name' },
          { key: 'price', title: 'Price' },
          { key: 'sku', title: 'SKU' },
        ],
        defaultKey: 'name',
        defaultDir: 'asc',
      },
      pagination: { pageSize: 25, pageSizes: [25, 50] },
      columns: [
        { key: 'image', title: '', type: 'image', locked: true, search: false },
        { key: 'name', title: 'Product', sortable: false },
        { key: 'sku', title: 'SKU', sortable: false },
        { key: 'status', title: 'Status', type: 'status', sortable: false },
        { key: 'price', title: 'Price', type: 'amount', sortable: false },
      ],
    }
  }

  if (type === 'order') {
    return {
      ...chrome,
      key: 'resource-list-order',
      sort: {
        fields: [
          { key: 'date', title: 'Date' },
          { key: 'amount', title: 'Amount' },
          { key: 'name', title: 'Order' },
        ],
        defaultKey: 'date',
        defaultDir: 'desc',
      },
      pagination: { pageSize: 25, pageSizes: [25, 50] },
      columns: [
        { key: 'name', title: 'Order', locked: true, sortable: false },
        { key: 'status', title: 'Status', type: 'status', sortable: false },
        { key: 'amount', title: 'Amount', type: 'amount', sortable: false },
        { key: 'channel', title: 'Channel', sortable: false },
        { key: 'date', title: 'Date', type: 'date', sortable: false },
      ],
    }
  }

  if (type === 'charge') {
    return {
      ...chrome,
      key: 'resource-list-charge',
      sort: {
        fields: [
          { key: 'date', title: 'Date' },
          { key: 'amount', title: 'Amount' },
          { key: 'name', title: 'Charge' },
        ],
        defaultKey: 'date',
        defaultDir: 'desc',
      },
      pagination: { pageSize: 25, pageSizes: [25, 50] },
      columns: [
        { key: 'name', title: 'Charge', locked: true, sortable: false },
        { key: 'status', title: 'Status', type: 'status', sortable: false },
        { key: 'amount', title: 'Amount', type: 'amount', sortable: false },
        { key: 'method', title: 'Method', sortable: false },
        { key: 'date', title: 'Date', type: 'date', sortable: false },
      ],
    }
  }

  return {
    ...chrome,
    key: 'resource-list-invoice',
    sort: {
      fields: [
        { key: 'name', title: 'Invoice' },
        { key: 'amount', title: 'Amount' },
      ],
      defaultKey: 'name',
      defaultDir: 'asc',
    },
    pagination: { pageSize: 10, pageSizes: [10, 25] },
    columns: [
      { key: 'name', title: 'Invoice', locked: true, sortable: false },
      { key: 'status', title: 'Status', type: 'status', sortable: false },
      { key: 'amount', title: 'Amount', type: 'amount', sortable: false },
      { key: 'email', title: 'Customer', sortable: false },
    ],
  }
}

/** Toolbar filter keys owned by SchemaTable (popover skips these). */
export function resourceListToolbarFilterKeys(type: ResourceCatalogType): string[] {
  return (RESOURCE_EXTRA_FILTERS[type] ?? []).map((group) => group.key)
}

